package main
import (
    "fmt"
    "os"
    "strings"

    "github.com/spf13/cobra"
)

var (
    configPath string
    onlyPatterns []string
    excludePatterns []string
    unwrapExports bool
    jsTsconfigPaths bool = true
    jsWorkspaces bool = true
    pythonExcludeConditional bool
)

func main() {
    rootCmd := &cobra.Command{
        Use:   "dep-tree [command]",
        Short: "",
        Long:  "",
        Example: `$ dep-tree src/index.ts
$ dep-tree entropy src/index.ts
$ dep-tree tree package/main.py --unwrap-exports
$ dep-tree check`,
        Run: func(cmd *cobra.Command, args []string) {
            // default is entropy
            if len(args) == 0 {
                cmd.Help()
                os.Exit(0)
            }
            // treat as entropy
            // We need to handle global flags already parsed
            // Run entropy logic with args as entrypoints
            runEntropy(cmd, args)
        },
    }
    // Add ascii logo to help template? Cobra prints Usage etc. We'll set custom help template to include ascii for root.
    ascii := `
      ____         _ __       _
     |  _ \   ___ |  _ \    _| |_  _ __  ___   ___
     | | | | / _ \| |_) |  |_   _||  __|/ _ \ / _ \
     | |_| ||  __/| .__/     | |  | |  |  __/|  __/
     |____/  \__| |_|        | \__|_|   \___| \___|
`
    // Override help template for root
    rootCmd.SetHelpTemplate(ascii + "\n{{with (or .Long .Short)}}{{.}}\n\n{{end}}Usage:\n  {{.UseLine}}\n\nExamples:\n{{.Example}}\n\n{{if .HasAvailableSubCommands}}Visualize your dependencies graphically\n  {{range .Commands}}{{if (and .IsAvailableCommand (eq .GroupID \"\"))}}{{if (or (eq .Name \"entropy\") (eq .Name \"tree\"))}}  {{rpad .Name .NamePadding}} {{.Short}}\n{{end}}{{end}}{{end}}\nCheck your dependencies against your own rules\n  {{range .Commands}}{{if (and .IsAvailableCommand (eq .Name \"check\"))}}  {{rpad .Name .NamePadding}} {{.Short}}\n{{end}}{{end}}\nDisplay what are the dependencies between two portions of code\n  {{range .Commands}}{{if (and .IsAvailableCommand (eq .Name \"explain\"))}}  {{rpad .Name .NamePadding}} {{.Short}}\n{{end}}{{end}}\nAdditional Commands:\n  {{range .Commands}}{{if (and .IsAvailableCommand (not (or (eq .Name \"entropy\") (eq .Name \"tree\") (eq .Name \"check\") (eq .Name \"explain\"))))}}  {{rpad .Name .NamePadding}} {{.Short}}\n{{end}}{{end}}{{end}}{{if .HasAvailableLocalFlags}}Flags:\n{{.LocalFlags.FlagUsages | trimTrailingWhitespaces}}\n\n{{end}}{{if .HasAvailableInheritedFlags}}Global Flags:\n{{.InheritedFlags.FlagUsages | trimTrailingWhitespaces}}\n\n{{end}}{{if .HasHelpSubCommands}}Additional help topics:\n{{range .Commands}}{{if .IsAdditionalHelpTopicCommand}}  {{rpad .CommandPath .CommandPathPadding}} {{.Short}}\n{{end}}{{end}}{{end}}{{if .HasAvailableSubCommands}}Use \"{{.CommandPath}} [command] --help\" for more information about a command.\n{{end}}`)

    rootCmd.PersistentFlags().StringVarP(&configPath, "config", "c", ".dep-tree.yml", "path to dep-tree's config file.")
    rootCmd.PersistentFlags().StringArrayVar(&onlyPatterns, "only", nil, "Files that do not match this glob pattern will be ignored. You can provide an arbitrary number of --only flags.")
    rootCmd.PersistentFlags().StringArrayVar(&excludePatterns, "exclude", nil, "Files that match this glob pattern will be ignored. You can provide an arbitrary number of --exclude flags.")
    rootCmd.PersistentFlags().BoolVar(&unwrapExports, "unwrap-exports", false, "trace re-exported symbols to the file where they are declared. (default false)")
    rootCmd.PersistentFlags().BoolVar(&jsTsconfigPaths, "js-tsconfig-paths", true, "follow the tsconfig.json paths while resolving imports. (default true)")
    rootCmd.PersistentFlags().BoolVar(&jsWorkspaces, "js-workspaces", true, "take the workspaces attribute in the root package.json into account for resolving paths. (default true)")
    rootCmd.PersistentFlags().BoolVar(&pythonExcludeConditional, "python-exclude-conditional-imports", false, "exclude imports wrapped inside if or try statements. (default false)")

    // Version
    rootCmd.PersistentFlags().BoolP("help", "h", false, "help for dep-tree")
    rootCmd.PersistentFlags().BoolP("version", "v", false, "version for dep-tree")
    rootCmd.Version = "v0.23.4"
    rootCmd.SetVersionTemplate("dep-tree version {{.Version}}\n")

    // Subcommands
    entropyCmd := &cobra.Command{
        Use:   "entropy",
        Short: "(default) Renders a 3d force-directed graph in the browser",
        Run: func(cmd *cobra.Command, args []string) {
            runEntropy(cmd, args)
        },
    }
    var noBrowserOpen bool
    var renderPath string
    var enableGui bool
    entropyCmd.Flags().BoolVar(&noBrowserOpen, "no-browser-open", false, "Disable the automatic browser open while rendering entropy")
    entropyCmd.Flags().StringVar(&renderPath, "render-path", "", "Sets the output path of the rendered html file")
    entropyCmd.Flags().BoolVar(&enableGui, "enable-gui", false, "Enables a GUI for changing rendering settings")

    treeCmd := &cobra.Command{
        Use:   "tree",
        Short: "Render the dependency tree starting from the provided entrypoint",
        Run: func(cmd *cobra.Command, args []string) {
            runTree(cmd, args)
        },
    }
    var jsonOutput bool
    treeCmd.Flags().BoolVar(&jsonOutput, "json", false, "render the dependency tree in a machine readable json format")

    checkCmd := &cobra.Command{
        Use:   "check",
        Short: "Checks that the dependency rules defined in the configuration file are not broken",
        Run: func(cmd *cobra.Command, args []string) {
            runCheck(cmd, args)
        },
    }

    explainCmd := &cobra.Command{
        Use:   "explain",
        Short: "Shows all the dependencies between two parts of the code",
        Args:  cobra.ExactArgs(2),
        Run: func(cmd *cobra.Command, args []string) {
            runExplain(cmd, args)
        },
    }
    var overlapLeft bool
    var overlapRight bool
    explainCmd.Flags().BoolVarP(&overlapLeft, "overlap-left", "l", false, "When there's an overlap between the files at the left and the right, keep the ones at the left")
    explainCmd.Flags().BoolVarP(&overlapRight, "overlap-right", "r", false, "When there's an overlap between the files at the left and the right, keep the ones at the right")

    configCmd := &cobra.Command{
        Use:   "config",
        Aliases: []string{"init"},
        Short: "Generates a sample config in case that there's not already one present",
        Run: func(cmd *cobra.Command, args []string) {
            runConfig(cmd, args)
        },
    }

    rootCmd.AddCommand(entropyCmd, treeCmd, checkCmd, explainCmd, configCmd)

    // Handle version flag manually because cobra's version handling prints to stdout but we want exact output?
    // Cobra already handles -v

    if err := rootCmd.Execute(); err != nil {
        fmt.Fprintln(os.Stderr, err)
        os.Exit(1)
    }
}

func runEntropy(cmd *cobra.Command, args []string) {
    fmt.Println("entropy", args, "config", configPath, "only", onlyPatterns, "exclude", excludePatterns)
}

func runTree(cmd *cobra.Command, args []string) {
    fmt.Println("tree", args)
}

func runCheck(cmd *cobra.Command, args []string) {
    fmt.Println("check")
}

func runExplain(cmd *cobra.Command, args []string) {
    fmt.Println("explain", args)
}

func runConfig(cmd *cobra.Command, args []string) {
    fmt.Println("config")
}
GO
cat /workspace/src/main.go
"}

